var rootHelp = "typeship — command-line client for Typeship\n\nUsage:\n  typeship <resource> <command> [flags]\n  typeship <command>\n\nResources:\n  projects         Create a Project\n  specs            Get a Spec\n  spec-revisions   List Spec Revisions\n  targets          Create a Target\n  deliveries       Create a Delivery\n  generations      Get a Generation\n  drafts           List Drafts\n  releases         List Releases\n  files            Get a File\n  packages         Generate a package\n  organization     Get the Organization\n  api-keys         List API keys\n\nCommands:\n  help       Show this help\n  version    Print the version\n  api        Call any endpoint through the SDK's raw capability\n  docs       Read the API reference and guides\n  completion Print bash, zsh, or fish completion\n  init       Configure this machine\n  agent-guide Print the agent contract\n  doctor     Check the local installation\n  upgrade    Update this installed binary\n  config     Read or update per-profile configuration\n  mcp        Print or install the MCP entry\n  feedback   Send product feedback\n\nFlags:\n  -h, --help       Show help\n  -v, --version    Show version\n  --dry-run        Preview an API request without sending it\n  --read-only      Allow only operations classified as reads\n  --tools <list>   Allow selected resources, tool names, or resource.method\n  --profile <name> Use isolated credentials and configuration\n\nCredentials: --credentials @<file>|- or TYPESHIP_CREDENTIALS (JSON keyed by exact security-scheme name).\nCredential precedence is flags, then environment, then saved credentials; named credentials override convenience credentials within a source.\n\nRun 'typeship <resource> --help' for its commands, or 'typeship <resource> <command> --help' for flags and an example.\n"

